<div class="payment-section">

  <div class="payment-cards">

    <div class="card prev-card">
      <div class="card-title">Previous Month</div>
      <div class="card-value" style="color:${S};">
        ${I}
      </div>
    </div>

    <div class="card current-card">
      <div class="card-title">
        Current Month <br/>
        <span style="font-size:13px; color:#555;">
          (${n.format("MMMM")} / ${n.format("YYYY")})
        </span>
      </div>

      <div class="card-value" style="color:#3b82f6;">
        ${l(y)}
      </div>

      <div class="card-sub" style="color:#16a34a; font-weight:600;">
        Received: ${l(j)}
       </div>
    </div>

    <div class="card final-card">
      <div class="card-title">Net Payable</div>

      <div class="card-value" style="color:${B};">
        ${l(s)}
      </div>

      <div class="card-sub">
        ${P}
      </div>
    </div>

  </div>

  ${s>0?`
  <div class="qr-box">
    <div class="qr-header">
      <div>
        <div class="qr-title">Pay with QR</div>
        <div class="qr-sub">Scan to pay instantly</div>
      </div>

      <div class="qr-amount" style="color:red;">
        ${l(s)}
      </div>
    </div>

    <div class="qr-image">
      <div class="qr-placeholder">QR not provided</div>
    </div>

    <div class="qr-instruction">
      Tip: Open UPI app → Scan QR → Confirm payment.
    </div>
  </div>
  `:""}

</div>
